  function riskLabel(risk){return risk.stage_label==='stage_1_12_month'?'Stage 1 reviewed 12-month':risk.stage_label==='stage_3_credit_impaired'?'Stage 3 credit-impaired':'Stage 2 lifetime';}
  function exactAmount(n){const sign=n<0n?'-':'',digits=(n<0n?-n:n).toString().padStart(3,'0');return sign+digits.slice(0,-2)+'.'+digits.slice(-2);}
