  function cashMeasurementFacts(c){return facts([['Retained measurement reference',c.review_id],['Cash measurement date',c.as_of_date],['Calculated at',c.calculated_at],['Verified gross carrying',c.gross_carrying_amount],['Expected cash present value',c.expected_cash_present_value],['Unrounded weighted expected cash present value',c.weighted_expected_cash_present_value_raw],['Currency rounding adjustment',c.currency_rounding_adjustment],['Expected credit loss',c.ecl_amount]]);}
  function cashFacts(c){return facts([['Cash application reference',c.application_id],['Cash measurement date',c.as_of_date],c.opening_renewal_review_id?['Opening renewal review',c.opening_renewal_review_id]:['Opening impaired assessment',c.opening_assessment_id??'Unavailable'],['Opening cutoff',c.opening_cutoff_date??'Unavailable'],['Verified gross carrying after cash',c.gross_carrying_amount??'Unavailable']]);}
  function cashReviewRows(){if(!candidate?.impaired_cash_reviews?.length||!can('accounting.period.close.prepare'))return '';return '<h4>Dated impaired-cash measurement evidence</h4>'+candidate.impaired_cash_reviews.map(c=>cashFacts(c)+(c.current_confirmation?'<p>Current retained measurement matches this cash event.</p>':'')+button(`data-impaired-cash="${c.application_id}"`,'Review cash-date expected receipts')).join('');}
